def fizzbuzz(n):
    result = []
    for i in range(1, n + 1):
        if i % 3 == 0 and i % 5 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))
    return result

def parsear_duracion(s):
    if not s:
        return 0
    total = 0
    for char in s:
        if char.isdigit():
            total += int(char)
        elif char == 'h':
            total += 60
        elif char == 'm':
            total += 1
    return total

